TLM.f("Sancti/10-17",{"officium":"S. Margaritæ Mariæ Alaquoque Virginis","rule":["vide C6","Gloria"],"ruleInherited":["Gloria"],"fallback":"Commune/C6","sections":{"Introitus":[{"k":"ref","la":"Cant 2:3"},{"k":"text","la":"Sub umbra illíus, quem desideráveram, sedi: et fructus ejus dulcis gútturi meo."},{"k":"ref","la":"Ps 83:2-3"},{"k":"text","la":"Quam dilécta tabernácula tua, Dómine virtútum! concupíscit, et déficit ánima mea in átria Dómini."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Sub umbra illíus, quem desideráveram, sedi: et fructus ejus dulcis gútturi meo."}],"Oratio":[{"k":"text","la":"Dómine Jesu Christe, qui investigábiles divítias Cordis tui beátæ Margarítæ Maríæ Vírgini mirabíliter revelásti: da nobis ejus méritis et imitatióne; ut, te in ómnibus et super ómnia diligéntes, jugem in eódem Corde tuo mansiónem habére mereámur:"},{"k":"macro","name":"Qui vivis"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Ephésios."},{"k":"ref","la":"Ephes 3:8-9; 14-19"},{"k":"text","la":"Fratres: Mihi ómnium sanctórum mínimo data est grátia hæc, in géntibus evangelizáre investigábiles divítias Christi, et illumináre omnes, quæ sit dispensátio sacraménti abscónditi a sǽculis in Deo, qui ómnia creávit. Hujus rei grátia flecto génua mea ad Patrem Dómini nostri Jesu Christi, ex quo omnis patérnitas in cælis et in terra nominátur, ut det vobis secúndum divítias glóriæ suæ, virtúte corroborári per Spíritum ejus in interiórem hóminem: Christum habitáre per fidem in córdibus vestris: in caritáte radicáti et fundáti, ut póssitis comprehéndere cum ómnibus sanctis, quæ sit latitúdo et longitúdo et sublímitas et profúndum: scire étiam supereminéntem sciéntiæ caritátem Christi, ut impleámini in omnem plenitúdinem Dei."}],"Graduale":[{"k":"ref","la":"Cant 8:7"},{"k":"text","la":"Aquæ multæ non potuérunt exstínguere caritátem, nec flúmina óbruent illam."},{"k":"ref","la":"Ps 72:26"},{"k":"text","la":"Defécit caro mea et cor meum: Deus cordis mei, et pars mea Deus in ætérnum. Allelúja, allelúja."},{"k":"ref","la":"Cant 7:10"},{"k":"text","la":"Ego dilécto meo, et ad me conversio ejus. Allelúja."}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja"},{"k":"rubric","la":"Prov 9:5"},{"k":"text","la":"Veníte, comédite panem meum et bíbite vinum, quod míscui vobis."},{"k":"ref","la":"Ps 30:20"},{"k":"text","la":"Quam magna multitúdo dulcédinis tuæ, Dómine, quam abscondísti timéntibus te. Allelúja."}],"Tractus":[{"k":"ref","la":"Ps 83:3-4"},{"k":"text","la":"Cor meum et caro mea exsultavérunt in Deum vivum."},{"k":"text","la":"Etenim passer invénit sibi domum: et turtur nidum sibi, ubi ponat pullos suos.","mark":"V"},{"k":"text","la":"Altária tua, Dómine virtútum: Rex meus et Deus meus.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum."},{"k":"ref","la":"Matt 11:25-30"},{"k":"text","la":"In illo témpore: Respóndens Jesus, dixit: Confíteor tibi, Pater, Dómine cæli et terræ, quia abscondísti hæc a sapiéntibus et prudéntibus, et revelásti ea párvulis. Ita, Pater: quóniam sic fuit plácitum ante te. Omnia mihi trádita sunt a Patre meo. Et nemo novit Fílium nisi Pater: neque Patrem quis novit nisi Fílius, et cui volúerit Fílius reveláre. Veníte ad me, omnes, qui laborátis et oneráti estis, et ego refíciam vos. Tóllite jugum meum super vos, et discite a me, quia mitis sum et húmilis corde: et inveniétis réquiem animábus vestris. Jugum enim meum suave est et onus meum leve."}],"Offertorium":[{"k":"ref","la":"Zach 9:17"},{"k":"text","la":"Quid bonum ejus est et quid pulchrum ejus, nisi fruméntum electórum et vinum gérminans vírgines?"}],"Secreta":[{"k":"text","la":"Accépta tibi sint, Dómine, plebis tuæ múnera: et concéde; ut ignis ille divínus nos inflámmet, quo de Corde Fílii tui emisso beáta Margaríta María veheménter æstuávit."},{"k":"macro","name":"Per eundem"}],"Communio":[{"k":"ref","la":"Cant 6:2"},{"k":"text","la":"Ego dilécto meo, et diléctus meus mihi, qui páscitur inter lília."}],"Postcommunio":[{"k":"text","la":"Córporis et Sánguinis tui, Dómine Jesu, sumptis mystériis: concéde nobis, quǽsumus, beáta Margaríta María Vírgine intercedénte; ut, supérbis sǽculi vanitátibus exútis, mansuetúdinem et humilitátem Cordis tui indúere mereámur:"},{"k":"macro","name":"Qui vivis"}]},"hr":{"e6c0dacfb273c1f8":{"t":"Pj 2, 3, Ps 83, 2-3\n(Pj 2, 3) [Prema K.S.:] Bila sam željna hlada njezina i sjedoh, plodovi njeni slatki su grlu mome. (Ps 83, 2-3) Kako su mili stanovi tvoji, Gospodine vojska! Duša moja čeznu i gine za dvorovima Gospodnjim.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Pj 2, 3) [Prema K.S.:] Bila sam željna hlada njezina i sjedoh, plodovi njeni slatki su grlu mome.","v":"cant → ∅","kn":"(Posl. 28, 17). Strašno je ovo mjesto; ovdje . je dom Gospodnji i vrata nebeska i zvat će se. dvor Božji. (Ps. 83, 2) Kako su mili stanovi Tvoji, Gospodine nad vojskama! Čezne i gine duša^ moja za dvorima Gospodnjim! Slava Ocu . . . Strašno . . .","knRef":"Kniewald 1942, str. 834–835 (snimka 418) (OCR)"},"01bd5c3cc993c706":{"t":"<i>Pomolimo se</i>.\nGospodine Isuse Kriste, koji si čudesno objavio blaženoj Margareti Mariji djevici neistraživa bogatstva svoga Srca, daj nam da po njezinim zaslugama i primjeru zavrijedimo, ljubeći te u svemu i iznad svega, imati neprestano boravište u tvom Srcu:\n<i>koji živiš i kraljuješ s Bogom Ocem u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Gašpoidime Isuse Kriste, koji ei blaženoj djevici Margareti objavio nedokučiva bogatstva Srca svoga, daj, da njezinim zaslugama i nasljedovanjem ljubeći Tebe u svemu i nada sve zavrijedimo imati neprestani stari u istom Srcu Tvomu, koji živiš i kraljuješ...","knRef":"Kniewald 1942, str. 740–741 (snimka 371) (OCR)"},"c8e4b9c115f51ef4":{"t":"Ef 3, 8-9 i 14-19\nČitanje Poslanice bl. Pavla apostola Efežanima. Braćo, meni, najmanjemu od svih svetih, dana je milost da poganima navijestim nedokučivo bogatstvo Kristovo i da svima protumačim, kako se ostvarilo otajstvo oduvijek skriveno u Bogu koji je sve stvorio. Zato prigibam svoja koljena pred Ocem Gospodina našega Isusa Krista, od koga potječe svako očinstvo na nebu i na zemlji, da vam po svojoj obilnoj slavi dade, te njegovim Duhom ojačate za unutrašnjeg čovjeka, da po vjeri Krist stanuje u vašim srcima i da u ljubavi ukorijenjeni i utvrđeni možete sa svim svetima razumjeti širinu i dužinu i visinu i dubinu i spoznati Kristovu ljubav, koja nadilazi svaku spoznaju, da se napunite svakom puninom Božjom.","kn":"Čitanje poslanice bi. Favla apostola Efežanima (3, 8-9. 14-19). Braćo! Meni najmanjemu od svih svetih dana je ova milost, da, navješćujem heznabošcima nedokučivo Kristovo bogatstvoj i da svima javim, kakva je uredk'a tajne, koja je od vijeka sakrivena u Bogu, koji je sve stvorio. Zato prigibam svoja koljena pred Ocem Gospodina našega Isusa Krista, po kojemu .postaje svaka obitelj na nebu r na zemlji, da vam po svojoj .. obilnoj slavi i dobroti dadne, da se po njegovu duhu pojačate za unutrašnjega čovjeka, da po vjeri Krist stanuje u vašim srcima. Da ukorijenjeni i utvrđeni u ljubavi sa svima svetima možete dokučiti, koja je širina i dužina i visina i dubina, i da možete poznati Kristovu ljubav, koja prelazi svako znanje, da se naipunite svakim Božjim obiljem;","knRef":"Kniewald 1942, str. 740–741 (snimka 371) (OCR)"},"9aafa2ca88484363":{"t":"Pj 8, 7, Ps 72, 26\n(Pj 8, 7) Mnoge vode ne mogu ugasiti ljubavi, niti je rijeke mogu zagušiti. (Ps 72, 26) Sve da nestane moga tijela i moga srca, ti ćeš ipak ostati Bog srca moga i moja vječna baština.\n\nPj 7, 10\n<i>Aleluja</i>, <i>aleluja</i>.\nJa pripadam onome koga ljubim, a on pripada meni. <i>Aleluja</i>."},"bb0bd8107f5e0717":{"t":"Mt 11, 25-30\nSlijedi sveto Evanđelje po Mateju. U ono vrijeme: Zahvaljujem ti, Oče, Gospodaru neba i zemlje jer si ovo sakrio mudrima i razumnima, a objavio malenima. Da, Oče, jer ti se svidjelo tako! Moj je Otac predao meni sve, i nitko ne pozna Sina nego Otac, niti tko pozna Oca nego Sin i komu Sin hoće da objavi. Dođite k meni svi koji ste umorni i opterećeni i ja ću vas okrijepiti. Uzmite na sebe moj jaram i učite se od mene jer sam ja krotka i ponizna srca i naći ćete pokoj svojim dušama. Jer je moj jaram sladak i moje breme lako.","kn":"t Slijedi sveto evanđelje po Mateju (11, 25-30). U ono vrijeme reče Isus: Hvalim, ti. Oče, Gospodaru neba i zemlje, jer si ovo. sakrio mudrima i razumnima. a objavio to malenima. Da, Oče, jer ti se svidjelo tako! Moj je Otac predao meni sve, i nitko ne pozna Sina nego Otac, niti tko pozna Oca nego Sin, i komu Sin hoće da objavi. Dođite k meni svi, koji ste umorni i opterećeni i ja ću vas okrijepiti. Uzmite na sebe moj jaram i učite se od mene, jer sam ja krotak i ponizan u srcu i naći ćete pokoj svojim dušama. Jer je moj jaram sladak i moje breme lako.","knRef":"Kniewald 1942, str. 476–477 (snimka 239) (OCR)"},"88270ec6e243b5ea":{"t":"Zah 9, 17\nIma li u njega išta tako vrijedno i tako lijepo kao što je kruh odabranih i vino iz kojega rastu djevice?"},"a7272f1e6483120c":{"t":"Bili ti, Gospodine, ugodni darovi tvoga naroda i daj da nas rasplamti onaj božanski oganj koji je izišao iz Srca tvoga Sina i kojim je žarko gorjela blažena Margareta Marija.\n<i>Po istom Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Primi, Gospodine, darove puka svoga i dopusti, da inas rasplamti onaj božanski oganj Srca Sina Tvoga, kojim je gorjela blažena Margareta, po ištom G. n. ‘ .","knRef":"Kniewald 1942, str. 740–741 (snimka 371) (OCR)"},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti. Oče svemogući, vječni Bože, po Kristu, Gospotdiniu našemu, po kome veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti. Nebesa Te i nebeske moći i blaženi serafini, zadružnim klicanjem zajedno slave. Zapovijedi, molimo, da se i naši glasovi združe s njihovima, smjernim isippvijedanjem govoreći:","knRef":"Kniewald 1942, str. 18–19 (snimka 10) (OCR)"},"0c53d7fbb6ca1173":{"t":"Pj 6, 2\nJa pripadam onome koga ljubim, a meni pripada on koji pase stado među ljiljanima."},"aee5431a32e913ab":{"t":"<i>Pomolimo se</i>.\nPošte smo primili otajstva tijela i krvi tvoje, Gospodine Isuse, daj nam, molimo, da po zagovoru blažene Margarete Marije djevice zavrijedimo oslobođeni od oholih taština svijeta postići krotkost tvoga Srca.\n<i>Koji živiš i kraljuješ s Bogom Ocem u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Primivši, Gospodine Isuse, ■ otajstva tijela i krvi Tvoje, dopusti, molimo, da zagovorom blažene djeVice Tvoje Margarete prezremo ohole taštine ■ ovoga svijeta ,i prihvatimo krotkost i poniznost Srca Tvoga, koji živiš .i kraljuješ,..","knRef":"Kniewald 1942, str. 740–741 (snimka 371) (OCR)"}}});
